        }

        .sidemenu {
            &__btn {
                display: block;
                width: 80px;
                height: 80px;
                border: none;
                position: relative;
                z-index: 100;
                appearance: none;
                cursor: pointer;
                outline: none;

                span {
                    display: block;
                    width: 30px;
                    height: 3px;
                    margin: auto;
                    background: #fff;
                    border-radius: 5px;
                    position: absolute;
                    top: 0;
                    bottom: 0;
                    left: 0;
                    right: 0;
                    transition: all .4s ease;

                    &.top {
                        transform: translateY(-8px);
                    }

                    &.bottom {
                        transform: translateY(8px);
                    }
                }
                &.active{
                    .top {
                        transform: rotate(-45deg);
                        background: #CFCFCF;
                        height: 4px;
                        width: 25px;
                        border-radius: 10%;
                    }
                    .mid{
                        transform: translateX(-20px) rotate(360deg);
                        opacity: 0;
                    }
                    .bottom {
                        transform: rotate(45deg);
                        background: #CFCFCF;
                        height: 4px;
                        width: 25px;
                        border-radius: 10%;
                    }
                }

            }

            &__wrapper {
                padding-top: 105px;
            }

            &__list {
                padding-top: 50px;
                list-style:none;
                padding: 0;
                margin: 0;
            }
        }
    }
    .translateX-enter{
        transform:translateX(200px);
        opacity: 0;
    }
    .translateX-enter-active,.translateX-leave-active{
        transform-origin: top left 0;
        transition-property: all;
        transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
        transition-duration: 500ms;
    }
    .translateX-leave-to{
        transform: translateX(200px);
        opacity: 0;
    }
